<template><div><DsPageHeader title="Importar variáveis (.cs)" subtitle="Revise e confirme os itens encontrados" icon="upload"/><DsPageShell><input type="file" accept=".cs" @change="selectFile"/><DsButton class="ml-2" :loading="loading" @click="preview">Analisar</DsButton><div v-if="dados" class="mt-5"><DsAlert variant="info">{{ dados.variaveis.length }} variável(is), {{ dados.formulas.length }} fórmula(s) e {{ dados.normalidades.length }} normalidade(s).</DsAlert><label v-for="v in dados.variaveis" :key="v.codigo" class="flex gap-2 border-b py-2"><input v-model="selecionadas" type="checkbox" :value="v.codigo" :disabled="v.existeNoBanco"/><code>{{ v.codigo }}</code><span>{{ v.nome }}</span><DsBadge v-if="v.existeNoBanco" variant="dark">Já existe</DsBadge></label><DsButton class="mt-4" :loading="loading" :disabled="!selecionadas.length" @click="confirmar">Importar selecionadas</DsButton></div><DsButton class="mt-5 ml-2" variant="secondary" to="/variaveis">Voltar</DsButton></DsPageShell></div></template>
<script setup lang="ts">import type { ImportacaoCsPreview } from '~/composables/useVariaveisApi'; definePageMeta({layout:'default'}); const api=useVariaveisApi();const swal=useSwal();const router=useRouter();const file=ref<File|null>(null);const dados=ref<ImportacaoCsPreview|null>(null);const selecionadas=ref<string[]>([]);const loading=ref(false);function selectFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null}async function preview(){if(!file.value)return;loading.value=true;try{dados.value=(await api.previewImportacaoCs(file.value)).data;selecionadas.value=dados.value.variaveis.filter(v=>!v.existeNoBanco).map(v=>v.codigo)}catch(e){await swal.toast(e instanceof Error?e.message:'Erro','error')}finally{loading.value=false}}async function confirmar(){if(!dados.value)return;loading.value=true;try{const r=await api.confirmarImportacaoCs({...dados.value,variaveisSelecionadas:selecionadas.value});await swal.toast(`${r.data.inseridas} variável(is) importada(s).`);await router.push('/variaveis')}catch(e){await swal.toast(e instanceof Error?e.message:'Erro','error')}finally{loading.value=false}}</script>

